window.DEX_DATA["sources:backport-c2fcad46421f7d50"]={"json":{"skins":[{"filename":"madame.png"}],"names":[{"name":"莉莉安"},{"name":"克里斯蒂"},{"name":"阿比盖尔"},{"name":"杰奎琳"},{"name":"夏琳"}],"chat":[{"lines":[{"text":"多么古朴的小镇，看看那些忙忙碌碌的工人。"},{"text":"我还有更重要的事，我要去买颗钻石。"}]},{"lines":[{"text":"我的司机在哪儿？他开车离开已经好几分钟了！"},{"text":"穿这双鞋，我实在站不了多久。"}]},{"lines":[{"text":"超级球？孩子，你也太容易满足了。我的球都是纯金的。"},{"text":"可它们特别容易磕坏，只好经常换新的。唉！"}]},{"lines":[{"text":"我让孙子出去见见世面，他带的东西可少了，只有一只小拉达。"},{"text":"还有蓝色西装，以及区区五百万宝可元。但愿他撑得住，唉……"}]}]}};
